// ============================================================
// TypeDefaults: Config
// ============================================================
// ConfigDefaults applies field-level default values to zero-valued fields.
func ConfigDefaults(v *Config) {
	if v.AccessTokenLifetimeSeconds == 0 {
		v.AccessTokenLifetimeSeconds = DefaultAccessTokenLifetimeSeconds
	}
	if v.RefreshTokenLifetimeSeconds == 0 {
		v.RefreshTokenLifetimeSeconds = DefaultRefreshTokenLifetimeSeconds
	}
	if v.KeyLifetimeSeconds == 0 {
		v.KeyLifetimeSeconds = DefaultKeyLifetimeSeconds
	}
	if v.NonceExpireSeconds == 0 {
		v.NonceExpireSeconds = DefaultNonceExpireSeconds
	}
	if v.JwkRefetchIntervalSeconds == 0 {
		v.JwkRefetchIntervalSeconds = DefaultJwkRefetchIntervalSeconds
	}
	if v.Oauth != nil {
		OAuthConfigDefaults(v.Oauth)
	}
}

// ============================================================
// TypeDefaults: OAuthConfig
// ============================================================
// OAuthConfigDefaults applies field-level default values to zero-valued fields.
func OAuthConfigDefaults(v *OAuthConfig) {
	if v.Audience == "" {
		v.Audience = DefaultAudience
	}
}

// ============================================================
// TypeUndefaults: Config
// ============================================================
// ConfigUndefaults resets fields that match their default values back to zero.
// Use before persisting to store only explicit user overrides.
func ConfigUndefaults(v *Config) {
	if v.AccessTokenLifetimeSeconds == DefaultAccessTokenLifetimeSeconds {
		v.AccessTokenLifetimeSeconds = 0
	}
	if v.RefreshTokenLifetimeSeconds == DefaultRefreshTokenLifetimeSeconds {
		v.RefreshTokenLifetimeSeconds = 0
	}
	if v.KeyLifetimeSeconds == DefaultKeyLifetimeSeconds {
		v.KeyLifetimeSeconds = 0
	}
	if v.NonceExpireSeconds == DefaultNonceExpireSeconds {
		v.NonceExpireSeconds = 0
	}
	if v.JwkRefetchIntervalSeconds == DefaultJwkRefetchIntervalSeconds {
		v.JwkRefetchIntervalSeconds = 0
	}
	if v.Oauth != nil {
		OAuthConfigUndefaults(v.Oauth)
	}
}

// ============================================================
// TypeUndefaults: OAuthConfig
// ============================================================
// OAuthConfigUndefaults resets fields that match their default values back to zero.
// Use before persisting to store only explicit user overrides.
func OAuthConfigUndefaults(v *OAuthConfig) {
	if v.Audience == DefaultAudience {
		v.Audience = ""
	}
}

// ============================================================
// Merge: Config
// ============================================================
// MergeConfig fills zero-valued fields in dst from src.
func MergeConfig(dst, src *Config) {
	if dst.Oauth == nil {
		dst.Oauth = src.Oauth
	} else if src.Oauth != nil {
		MergeOAuthConfig(dst.Oauth, src.Oauth)
	}
	if dst.AccessTokenLifetimeSeconds == 0 {
		dst.AccessTokenLifetimeSeconds = src.AccessTokenLifetimeSeconds
	}
	if dst.RefreshTokenLifetimeSeconds == 0 {
		dst.RefreshTokenLifetimeSeconds = src.RefreshTokenLifetimeSeconds
	}
	if dst.KeyLifetimeSeconds == 0 {
		dst.KeyLifetimeSeconds = src.KeyLifetimeSeconds
	}
	if dst.NonceExpireSeconds == 0 {
		dst.NonceExpireSeconds = src.NonceExpireSeconds
	}
	if dst.Issuer == "" {
		dst.Issuer = src.Issuer
	}
	if dst.JwkRefetchIntervalSeconds == 0 {
		dst.JwkRefetchIntervalSeconds = src.JwkRefetchIntervalSeconds
	}
	if dst.EntitlementsPolicy == "" {
		dst.EntitlementsPolicy = src.EntitlementsPolicy
	}
	if len(dst.EntitlementMappings) == 0 {
		dst.EntitlementMappings = src.EntitlementMappings
	}
	if len(dst.IdentityProfiles) == 0 {
		dst.IdentityProfiles = src.IdentityProfiles
	}
}

